# Expected prologue bytes for x86_64 Linux: push rbp; mov rbp, rsp
prologue = b'\x55\x48\x89'

# Iterate over blobs and try all single-byte XOR keys
results = []
for idx, blob in enumerate(blobs, start=1):
    # Normalize and convert to bytes
    data = bytes.fromhex(blob.replace(' ', ''))
    for key in range(256):
        decoded = bytes(b ^ key for b in data)
        if decoded.startswith(prologue):
            results.append((idx, key, chr(key)))
            break  # stop at first valid key

# Print results
flag = ""

for idx, key, char in results:
    print(f"Blob {idx}: key=0x{key:02x} ('{char}')")
    flag += char

print(f"Flag: {flag}")

